import { readFileSync } from 'node:fs';
import { join } from 'node:path';

/** The poster wall is inlined as SVG at build time (generated by scripts/make-hero.mjs from project tokens, no text or bitmaps). */
function inline(name: string) {
  const source = readFileSync(join(process.cwd(), 'public/art', name), 'utf8').trim();
  return source.replace(/ width="\d+" height="\d+">/, ' class="hero-svg" preserveAspectRatio="xMidYMid slice" focusable="false">');
}

export function HeroArt() {
  return (
    <>
      <div className="hero-layer hero-layer--back" dangerouslySetInnerHTML={{ __html: inline('hero-back.svg') }} />
      <div className="hero-layer hero-layer--front" dangerouslySetInnerHTML={{ __html: inline('hero-front.svg') }} />
    </>
  );
}
